int process_unique_identifier(char *line, void *data) {
    MessageContext *context = (MessageContext *)data;
    int index = atoi(line);
    Header *header = NULL;
    int i;

    // Trim whitespace from the line
    char *endptr;
    line = trim_whitespace(line, &endptr);

    if (line == NULL || *line == '\0') {
        return -1; // Invalid input
    }

    index = atoi(line);
    if (index < 0) {
        return -1; // Invalid index
    }

    // Search for the identifier in the headers
    for (i = 0; i < context->header_count; i++) {
        if (strcmp(context->headers[i].identifier, line) == 0) {
            header = &context->headers[i];
            break;
        }
    }

    if (header == NULL) {
        if (context->header_count >= MAX_HEADERS) {
            return -1; // No space for new header
        }
        header = &context->headers[context->header_count++];
        strcpy(header->identifier, line);
        header->index = index;
        header->reference = ++context->reference_number;
    } else if (header->index != index) {
        context->clear_cache = 1; // Index mismatch
    }

    header->index = index;
    header->reference = ++context->reference_number;

    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *context = (Context *)data;
    int index = 0;
    char *endptr;
    Header *header = NULL;

    // Convert line to integer index and trim whitespace
    index = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\0') {
        return -1;
    }

    // Search for the identifier in the context's headers
    for (int i = 0; i < context->header_count; ++i) {
        if (context->headers[i].index == index) {
            header = &context->headers[i];
            break;
        }
    }

    if (header == NULL) {
        // Add new header if it doesn't exist
        if (context->header_count >= MAX_HEADERS) {
            return -1;
        }
        header = &context->headers[context->header_count++];
        header->index = index;
        header->ref_count = 0;
    }

    if (header->ref_count > 0) {
        // If the header exists but the index does not match, clear cache
        if (header->index != index) {
            context->clear_cache = 1;
        }
    }

    // Update the reference number and index of the header
    header->ref_count++;
    header->index = index;

    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *context = (Context *)data;
    int index = 0;
    Header *header = NULL;

    // Convert line to an integer index
    if (sscanf(line, "%d", &index) != 1) {
        return -1;
    }

    // Trim whitespace from line
    char *trimmed = line;
    while (*trimmed && isspace(*trimmed)) {
        trimmed++;
    }

    // Check for valid unique identifier
    if (!*trimmed) {
        return -1;
    }

    // Search for identifier in headers
    for (int i = 0; i < context->header_count; i++) {
        if (strcmp(context->headers[i].identifier, trimmed) == 0) {
            header = &context->headers[i];
            break;
        }
    }

    // Add new header if not found
    if (!header) {
        if (context->header_count >= MAX_HEADERS) {
            return -1;
        }
        header = &context->headers[context->header_count];
        strncpy(header->identifier, trimmed, MAX_ID_LENGTH);
        header->index = index;
        header->reference = context->reference;
        context->header_count++;
    }

    // If index does not match, clear the cache
    if (header->index != index) {
        context->cache_dirty = 1;
    }

    // Update reference and index
    header->reference = context->reference;
    header->index = index;

    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *ctx = (Context *)data;
    int index = 0;
    char *endptr;

    if (!line || !ctx) {
        return -1;
    }

    index = strtol(line, &endptr, 10);
    if (endptr == line || index < 0) {
        return -1;
    }

    Header *header = find_header(ctx->headers, index);
    if (!header) {
        header = add_header(ctx->headers, index);
        if (!header) {
            return -1;
        }
    } else if (header->index != index) {
        ctx->clear_cache = 1;
    }

    header->ref_num = ctx->ref_count++;
    header->index = index;

    return 0;
}

int process_unique_id_line(char *line, void *data) {
    struct context *ctx = (struct context *)data;
    int index = 0;
    char *endptr;
    size_t i;

    // Convert line to integer index
    index = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\0') {
        return -1; // Invalid number
    }

    // Trim whitespace from the line
    while (isspace(*line)) {
        line++;
    }

    // Search for the identifier in the headers
    for (i = 0; i < ctx->header_count; i++) {
        if (strcmp(ctx->headers[i].id, line) == 0) {
            // Identifier found
            if (ctx->headers[i].index != index) {
                ctx->need_clear_cache = 1;
            }
            ctx->headers[i].ref_num = ctx->message.ref_num;
            ctx->headers[i].index = index;
            return 0;
        }
    }

    // Identifier not found, add a new header
    if (ctx->header_count >= MAX_HEADERS) {
        return -1; // Too many headers
    }

    strcpy(ctx->headers[ctx->header_count].id, line);
    ctx->headers[ctx->header_count].index = index;
    ctx->headers[ctx->header_count].ref_num = ctx->message.ref_num;
    ctx->header_count++;

    return 0;
}
